/** `id:Label` pairs joined by `|`, for every parameter the resource labels. */
const PACKED_PARAMETER_LABELS = [
  "-1154691:Hook Orientation At End|-1154690:Hook Orientation At Start",
  "-1154658:End Treatment At End|-1154657:End Treatment At Start",
  "-1152353:Number of items in the schedule group|-1140313:Damping ratio",
  "-1140270:Horizontal Offset value for parallel conduits",
  "-1114368:Show a Coordinate System Symbol for each Surface",
  "-1114367:Show Room Bounding Elements Dimmed and Underlay|-1017730:Fixed offset",
  "-1017024:Hook At End|-1017023:Hook At Start|-1015004:Is created by API",
  "-1010024:Blue value for RGB color spec. (for Use with XAML Data Template example)",
  "-1010023:Green value for RGB color spec. (for Use with XAML Data Template example)",
  "-1010022:Red value for RGB color spec. (for Use with XAML Data Template example)",
  "-1010021:Y-Radius Value for Ellipse (for Use with XAML Data Template example)",
  "-1010020:X-Radius Value for Ellipse (for Use with XAML Data Template example)",
  "-1010018:Group Name for Ribbon Combo Items (for Use with XAML)",
  "-1010017:Index Into Image File Name Array (for Use with XAML)|-1010013:Double",
  "-1010012:Integer|-1010011:Boolean|-1010010:Options|-1005400:Design Option Configuration",
].join("|");

/** `id:value=label` triples, keyed `id:value`. A label may contain `=`. */
function unpackValues(packed: string): Map<string, string> {
  const table = new Map<string, string>();
  for (const entry of packed.split("|")) {
    const separator = entry.indexOf("=");
    if (separator < 0) continue;
    table.set(entry.slice(0, separator), entry.slice(separator + 1));
  }
  return table;
}

function unpack(packed: string): Map<number, string> {
  const table = new Map<number, string>();
  for (const entry of packed.split("|")) {
    const separator = entry.indexOf(":");
    if (separator < 0) continue;
    table.set(Number(entry.slice(0, separator)), entry.slice(separator + 1));
  }
  return table;
}

let categoryLabels: Map<number, string> | undefined;
let categoryEnumNames: Map<number, string> | undefined;
let parameterEnumNames: Map<number, string> | undefined;
let parameterTypeNames: Map<number, string> | undefined;
let parameterValueNames: Map<string, string> | undefined;
let parameterLabels: Map<number, string> | undefined;
let ambiguousCategoryLabels: Set<number> | undefined;

/** Label Revit shows for a category id, including labels shared with siblings. */
export function revitCategoryLabel(categoryId: number): string | undefined {
  categoryLabels ??= unpack(PACKED_CATEGORY_LABELS);
  return categoryLabels.get(categoryId);
}

/** True when this category's label is shared and cannot name it on its own. */
export function isAmbiguousCategoryLabel(categoryId: number): boolean {
  ambiguousCategoryLabels ??= new Set(AMBIGUOUS_CATEGORY_LABEL_IDS);
  return ambiguousCategoryLabels.has(categoryId);
}

/** `OST_` enumerator name for a category id, without the prefix. */
export function revitCategoryEnumName(categoryId: number): string | undefined {
  categoryEnumNames ??= unpack(PACKED_CATEGORY_ENUM_NAMES);
  return categoryEnumNames.get(categoryId);
}

/** `BuiltInParameter` enumerator name, such as `WALL_USER_HEIGHT_PARAM`. */
export function parameterEnumName(parameterId: number): string | undefined {
  parameterEnumNames ??= unpack(PACKED_PARAMETER_ENUM_NAMES);
  return parameterEnumNames.get(parameterId);
}

/**
 * Autodesk's Forge name for a parameter neither label table names, such as
 * `wallHeightParam` for `-1001101`.
 *
 * These parameters exist and are typed, they simply carry no label because
 * Revit does not surface them. Naming one is better than printing its number.
 */
export function parameterTypeName(parameterId: number): string | undefined {
  parameterTypeNames ??= unpack(PACKED_PARAMETER_TYPE_NAMES);
  return parameterTypeNames.get(parameterId);
}

/**
 * What a parameter's stored number means, where the number names a choice
 * rather than measuring something.
 *
 * Revit keeps these in its integer value set, so a decoded `33615` under
 * `Rafter Cut` is "Plumb Cut" and a `0` under `Rafter or Truss` is "Truss".
 * `undefined` for the parameters that enumerate nothing, which is most of them.
 */
export function revitParameterValueName(
  parameterId: number,
  value: number,
): string | undefined {
  if (!Number.isInteger(value)) return undefined;
  parameterValueNames ??= unpackValues(PACKED_PARAMETER_VALUES);
  return parameterValueNames.get(`${parameterId}:${value}`);
}

/** Label Revit shows for a parameter id. */
export function revitParameterLabel(parameterId: number): string | undefined {
  parameterLabels ??= unpack(PACKED_PARAMETER_LABELS);
  return parameterLabels.get(parameterId);
}
